const item = $input.first().json;
const errors = [];

const required = ['Campaign_Name','Campaign_Type','Business_Objective','Desired_Outcome',
  'Offer','Budget','Timeline_Start','Timeline_End','Channels','Audience_Persona',
  'Requester_Name','Requester_Email'];

for (const field of required) {
  const val = item[field];
  if (val === undefined || val === null || val === '') {
    errors.push(`Missing required field: ${field}`);
  }
}

if (item.Budget !== undefined && (isNaN(Number(item.Budget)) || Number(item.Budget) <= 0)) {
  errors.push('Budget must be a positive number');
}

if (item.Timeline_Start && item.Timeline_End) {
  const start = new Date(item.Timeline_Start);
  const end = new Date(item.Timeline_End);
  if (end <= start) errors.push('Timeline_End must be after Timeline_Start');
}

const channelsArr = (item.Channels || '').split(',').map(s => s.trim()).filter(Boolean);
if (channelsArr.length === 0) errors.push('At least one channel must be provided');

return [{
  json: { ...item, Channels_Array: channelsArr, valid: errors.length === 0, validation_errors: errors }
}];

const campaign = $('Validate Inputs').first().json;
const personaItems = $('Fetch Persona').all();
const productItems = $('Fetch Product Context').all();
const factItems = $('Fetch Historical Facts').all();
let liveData = {};
try { liveData = $('Fetch Live Ad Platform Data (Placeholder)').first().json; } catch (e) { liveData = {}; }

const persona = personaItems.length > 0 ? personaItems[0].json.fields : null;
const product = productItems.length > 0 ? productItems[0].json.fields : null;

const historical_facts = factItems.length > 0
  ? factItems.map(i => ({
      metric: i.json.fields?.['Metric'],
      value: i.json.fields?.['Value'],
      source: i.json.fields?.['Source'],
      segment: i.json.fields?.['Segment/Channel'],
      date_range: i.json.fields?.['Date Range'],
      freshness: i.json.fields?.['Data Freshness Flag'] || 'unknown'
    }))
  : [];

const data_gaps = [];
if (!persona) data_gaps.push('No matching Persona record found for Audience_Persona: ' + campaign.Audience_Persona);
if (!product) data_gaps.push('No matching Product record found for this campaign');
if (historical_facts.length === 0) data_gaps.push('No historical performance facts on file for this product/persona combination');
if (!liveData || Object.keys(liveData).length === 0) data_gaps.push('Live data pull not configured (placeholder node)');

const normalized_data = {
  campaign: {
    name: campaign.Campaign_Name,
    type: campaign.Campaign_Type,
    objective: campaign.Business_Objective,
    desired_outcome: campaign.Desired_Outcome,
    offer: campaign.Offer,
    budget: Number(campaign.Budget),
    timeline: { start: campaign.Timeline_Start, end: campaign.Timeline_End },
    geography: campaign.Geography || 'Not specified',
    channels: campaign.Channels_Array,
    constraints: campaign.Constraints || 'None specified'
  },
  persona: persona || { note: 'data gap - see data_gaps' },
  product: product || { note: 'data gap - see data_gaps' },
  historical_facts,
  live_data_pull: liveData,
  data_gaps
};

return [{ json: {
  normalized_data,
  airtable_record_id: $('Create Campaign Record').first().json.id
} }];

