const raw = $json.content?.[0]?.text || $json.text || '';
let brief;
try { brief = JSON.parse(raw); } catch (e) {
  throw new Error('AI: Assemble Brief did not return valid JSON: ' + raw.slice(0,300));
}
return [{ json: {
  brief,
  facts: $('Parse Recommendations Output').first().json.facts,
  insights: $('Parse Recommendations Output').first().json.insights,
  hypotheses: $('Parse Recommendations Output').first().json.hypotheses,
  recommendations: $('Parse Recommendations Output').first().json.recommendations,
  airtable_record_id: $('Parse Recommendations Output').first().json.airtable_record_id,
  campaign_inputs: $('Validate Inputs').first().json
} }];

const { brief, facts, insights, hypotheses, recommendations, campaign_inputs } = $json;
const flags = [];

const requiredSections = ['executive_summary','business_objective','marketing_objective','target_audience',
  'customer_problem','offer_and_value_proposition','historical_insights','strategic_hypotheses',
  'campaign_strategy_and_messaging_pillars','creative_angles','channel_strategy','funnel_customer_journey',
  'recommended_kpis_and_measurement_plan','testing_plan','budget_considerations','risks_and_constraints',
  'open_questions','required_human_decisions'];
for (const s of requiredSections) {
  if (!brief[s] || brief[s].length === 0) flags.push('Missing or empty section: ' + s);
}

const validIds = new Set([
  ...facts.map(f => f.id), ...insights.map(i => i.id),
  ...hypotheses.map(h => h.id), ...recommendations.map(r => r.id)
]);
const allText = JSON.stringify(brief);
const cited = [...allText.matchAll(/\[([a-z]\d+)\]/g)].map(m => m[1]);
for (const id of cited) {
  if (!validIds.has(id)) flags.push('Brief cites unknown source id: ' + id);
}

const certaintyWords = ['will generate', 'guaranteed', 'proven', 'definitely'];
for (const h of (brief.strategic_hypotheses || [])) {
  if (certaintyWords.some(w => h.toLowerCase().includes(w))) {
    flags.push('Hypothesis stated with unwarranted certainty: ' + h.slice(0,60));
  }
}

if (new Date(campaign_inputs.Timeline_End) <= new Date(campaign_inputs.Timeline_Start)) {
  flags.push('Timeline_End is not after Timeline_Start');
}

const piiPattern = /[\w.+-]+@[\w-]+\.[a-z]{2,}|\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/i;
if (piiPattern.test(allText)) flags.push('Possible PII detected in brief text');

return [{ json: { ...$json, qa_passed: flags.length === 0, qa_flags: flags } }];
